namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    // Offline66 candidate. Historical58 source is unchanged; loaded Unity code is unchanged.
    // Small dependency-free JSON boundary for the existing RunCommand reference set.
    // No reflection, package loading, runtime serialization of arbitrary objects.
    public class Json58 : IEnumerable<Json58>
    {
        protected Dictionary<string, Json58> fields;
        protected List<Json58> items;
        protected object value;
        public Json58 this[string key]
        {
            get
            {
                Json58 v;
                return fields != null && fields.TryGetValue(key, out v) ? v : null;
            }

            set
            {
                fields[key] = value;
            }
        }

        public Json58 this[int i]
        {
            get
            {
                return items[i];
            }
        }

        public int Count
        {
            get
            {
                return items != null ? items.Count : fields != null ? fields.Count : 0;
            }
        }

        public void Add(Json58 v)
        {
            items.Add(v);
        }

        public IEnumerable<T> Values<T>()
        {
            return this.Select(v => (T)Convert.ChangeType(v.value, typeof(T), CultureInfo.InvariantCulture));
        }

        public IEnumerator<Json58> GetEnumerator()
        {
            return (items ?? (fields == null ? new List<Json58>() : fields.Values.ToList())).GetEnumerator();
        }

        IEnumerator IEnumerable.GetEnumerator()
        {
            return GetEnumerator();
        }

        public static implicit operator Json58(string v)
        {
            return v == null ? null : new Json58{value = v};
        }

        public static implicit operator Json58(int v)
        {
            return new Json58{value = v};
        }

        public static implicit operator Json58(long v)
        {
            return new Json58{value = v};
        }

        public static implicit operator Json58(float v)
        {
            return new Json58{value = (double)v};
        }

        public static implicit operator Json58(double v)
        {
            return new Json58{value = v};
        }

        public static implicit operator Json58(bool v)
        {
            return new Json58{value = v};
        }

        public static explicit operator string (Json58 v)
        {
            return v == null ? null : Convert.ToString(v.value, CultureInfo.InvariantCulture);
        }

        public static explicit operator int (Json58 v)
        {
            return Convert.ToInt32(v.value, CultureInfo.InvariantCulture);
        }

        public static explicit operator long (Json58 v)
        {
            return Convert.ToInt64(v.value, CultureInfo.InvariantCulture);
        }

        public static explicit operator double (Json58 v)
        {
            return Convert.ToDouble(v.value, CultureInfo.InvariantCulture);
        }

        public static explicit operator bool (Json58 v)
        {
            return Convert.ToBoolean(v.value, CultureInfo.InvariantCulture);
        }

        public static Json58 Wrap(object v)
        {
            if (v == null)
                return null;
            if (v is Json58)
                return (Json58)v;
            if (v is string)
                return (string)v;
            if (v is bool)
                return (bool)v;
            if (v is double)
                return (double)v;
            if (v is float)
                return (float)v;
            if (v is int)
                return (int)v;
            if (v is long)
                return (long)v;
            if (v is IEnumerable)
            {
                var a = new Arr58();
                foreach (var x in (IEnumerable)v)
                    a.Add(Wrap(x));
                return a;
            }

            throw new ArgumentException("Unsupported JSON boundary value: " + v.GetType().Name);
        }

        static string Quote(string text)
        {
            var b = new StringBuilder("\"");
            foreach (char c in text)
            {
                switch (c)
                {
                    case '"':
                        b.Append("\\\"");
                        break;
                    case '\\':
                        b.Append("\\\\");
                        break;
                    case '\b':
                        b.Append("\\b");
                        break;
                    case '\f':
                        b.Append("\\f");
                        break;
                    case '\n':
                        b.Append("\\n");
                        break;
                    case '\r':
                        b.Append("\\r");
                        break;
                    case '\t':
                        b.Append("\\t");
                        break;
                    default:
                        if (c < 32)
                            b.Append("\\u" + ((int)c).ToString("x4"));
                        else
                            b.Append(c);
                        break;
                }
            }

            return b.Append('"').ToString();
        }

        public override string ToString()
        {
            if (fields != null)
                return "{" + string.Join(",", fields.OrderBy(p => p.Key, StringComparer.Ordinal).Select(p => Quote(p.Key) + ":" + (p.Value == null ? "null" : p.Value.ToString()))) + "}";
            if (items != null)
                return "[" + string.Join(",", items.Select(v => v == null ? "null" : v.ToString())) + "]";
            if (value == null)
                return "null";
            if (value is string)
                return Quote((string)value);
            if (value is bool)
                return (bool)value ? "true" : "false";
            if (value is double)
            {
                double x = (double)value;
                if (double.IsNaN(x) || double.IsInfinity(x))
                    throw new ArgumentException("Nonfinite JSON number");
                return x.ToString("R", CultureInfo.InvariantCulture);
            }

            return Convert.ToString(value, CultureInfo.InvariantCulture);
        }

        public static bool DeepEquals(Json58 a, Json58 b)
        {
            return a == null ? b == null : b != null && a.ToString() == b.ToString();
        }

        public const int MaxInputChars66 = 65536;
        public static Json58 Parse(string text)
        {
            if (text.Length > MaxInputChars66)
                throw new ArgumentException("Small JSON budget exceeded; use streaming verification");
            int p = 0;
            var result = ParseValue(text, ref p, 0);
            Space(text, ref p);
            if (p != text.Length)
                throw new ArgumentException("Trailing JSON data");
            return result;
        }

        static void Space(string s, ref int p)
        {
            while (p < s.Length && char.IsWhiteSpace(s[p]))
                p++;
        }

        static string ParseString(string s, ref int p)
        {
            if (s[p++] != '"')
                throw new ArgumentException("JSON string expected");
            var b = new StringBuilder();
            while (p < s.Length)
            {
                char c = s[p++];
                if (c == '"')
                    return b.ToString();
                if (c == '\\')
                {
                    char e = s[p++];
                    switch (e)
                    {
                        case '"':
                        case '\\':
                        case '/':
                            b.Append(e);
                            break;
                        case 'b':
                            b.Append('\b');
                            break;
                        case 'f':
                            b.Append('\f');
                            break;
                        case 'n':
                            b.Append('\n');
                            break;
                        case 'r':
                            b.Append('\r');
                            break;
                        case 't':
                            b.Append('\t');
                            break;
                        case 'u':
                            b.Append((char)int.Parse(s.Substring(p, 4), NumberStyles.HexNumber, CultureInfo.InvariantCulture));
                            p += 4;
                            break;
                        default:
                            throw new ArgumentException("JSON escape");
                    }
                }
                else
                {
                    if (c < 32)
                        throw new ArgumentException("JSON control character");
                    b.Append(c);
                }
            }

            throw new ArgumentException("Unterminated JSON string");
        }

        static Json58 ParseValue(string s, ref int p, int depth)
        {
            if (depth > 128)
                throw new ArgumentException("JSON nesting limit");
            Space(s, ref p);
            if (p >= s.Length)
                throw new ArgumentException("JSON value expected");
            char c = s[p];
            if (c == '"')
                return ParseString(s, ref p);
            if (c == '{' || c == '[')
            {
                bool obj = c == '{';
                p++;
                Json58 result = obj ? (Json58)new Obj58() : new Arr58();
                Space(s, ref p);
                if (p < s.Length && s[p] == (obj ? '}' : ']'))
                {
                    p++;
                    return result;
                }

                while (true)
                {
                    Space(s, ref p);
                    string key = null;
                    if (obj)
                    {
                        key = ParseString(s, ref p);
                        if (result.fields.ContainsKey(key))
                            throw new ArgumentException("Duplicate JSON member");
                        Space(s, ref p);
                        if (s[p++] != ':')
                            throw new ArgumentException("JSON colon");
                    }

                    var v = ParseValue(s, ref p, depth + 1);
                    if (obj)
                        result[key] = v;
                    else
                        result.Add(v);
                    Space(s, ref p);
                    char end = s[p++];
                    if (end == (obj ? '}' : ']'))
                        break;
                    if (end != ',')
                        throw new ArgumentException("JSON separator");
                }

                return result;
            }

            foreach (string word in new[]{"true", "false", "null"})
                if (p + word.Length <= s.Length && string.CompareOrdinal(s, p, word, 0, word.Length) == 0)
                {
                    p += word.Length;
                    return word == "null" ? null : (Json58)(word == "true");
                }

            int start = p;
            while (p < s.Length && "-+0123456789.eE".IndexOf(s[p]) >= 0)
                p++;
            if (start == p)
                throw new ArgumentException("JSON token");
            return double.Parse(s.Substring(start, p - start), CultureInfo.InvariantCulture);
        }
    }

    public sealed class Obj58 : Json58
    {
        public Obj58()
        {
            fields = new Dictionary<string, Json58>(StringComparer.Ordinal);
        }

        public new static Obj58 Parse(string text)
        {
            return (Obj58)Json58.Parse(text);
        }
    }

    public sealed class Arr58 : Json58
    {
        public Arr58(params object[] values)
        {
            items = new List<Json58>();
            if (values.Length == 1 && values[0] is IEnumerable && !(values[0] is string) && !(values[0] is Json58))
            {
                foreach (var v in (IEnumerable)values[0])
                    Add(Wrap(v));
            }
            else
                foreach (var v in values)
                    Add(Wrap(v));
        }
    }

    // Prepared only; not imported, compiled in Unity, or executed in task64.
    // Public journal + externally hashed binary backup, never private-instance-only.
    public sealed class GlobalJournal64
    {
        public enum Kind
        {
            Float,
            LegacyInt,
            Integer,
            Vector,
            Matrix,
            Texture,
            FloatArray,
            VectorArray,
            MatrixArray,
            Buffer,
            ConstantBuffer
        }

        public sealed class Spec
        {
            public string name;
            public Kind kind;
        }

        public sealed class Entry
        {
            public Spec spec;
            public float scalar;
            public int integer;
            public Vector4 vector;
            public Matrix4x4 matrix;
            public float[] floats;
            public Vector4[] vectors;
            public Matrix4x4[] matrices;
            public Texture originalTexture;
            public string textureKind, assetGUID;
            public long localId;
            public bool restorable, mutated;
            public string reason;
        }

        public static GlobalJournal64 Active;
        public readonly List<Entry> entries = new List<Entry>();
        public string sourceId, externalPath, backupSHA256;
        public bool externalVerified;
        public static GlobalJournal64 Snapshot(string sourceId, string path, IEnumerable<Spec> specs)
        {
            if (Active != null)
                throw new InvalidOperationException("existing journal requires inspection, not replacement");
            var j = new GlobalJournal64{sourceId = sourceId, externalPath = path};
            foreach (var s in specs)
            {
                if (j.entries.Any(e => e.spec.name == s.name))
                    throw new ArgumentException("duplicate global name");
                var e = new Entry{spec = s, restorable = true};
                switch (s.kind)
                {
                    case Kind.Float:
                        e.scalar = Shader.GetGlobalFloat(s.name);
                        break;
                    // Legacy SetGlobalInt uses float storage in Unity6000.5. Keep
                    // the full original float, not only its integer truncation.
                    case Kind.LegacyInt:
                        e.scalar = Shader.GetGlobalFloat(s.name);
                        e.integer = Shader.GetGlobalInt(s.name);
                        break;
                    case Kind.Integer:
                        e.integer = Shader.GetGlobalInteger(s.name);
                        break;
                    case Kind.Vector:
                        e.vector = Shader.GetGlobalVector(s.name);
                        break;
                    case Kind.Matrix:
                        e.matrix = Shader.GetGlobalMatrix(s.name);
                        break;
                    case Kind.FloatArray:
                        e.floats = Shader.GetGlobalFloatArray(s.name);
                        e.restorable = e.floats != null && e.floats.Length > 0;
                        break;
                    case Kind.VectorArray:
                        e.vectors = Shader.GetGlobalVectorArray(s.name);
                        e.restorable = e.vectors != null && e.vectors.Length > 0;
                        break;
                    case Kind.MatrixArray:
                        e.matrices = Shader.GetGlobalMatrixArray(s.name);
                        e.restorable = e.matrices != null && e.matrices.Length > 0;
                        break;
                    case Kind.Texture:
                        e.originalTexture = Shader.GetGlobalTexture(s.name);
                        if (!e.originalTexture)
                            e.textureKind = "null";
                        else if (e.originalTexture == Texture2D.blackTexture)
                            e.textureKind = "builtin-black";
                        else if (e.originalTexture == Texture2D.whiteTexture)
                            e.textureKind = "builtin-white";
                        else if (e.originalTexture == Texture2D.grayTexture)
                            e.textureKind = "builtin-gray";
                        else
                        {
                            e.restorable = EditorUtility.IsPersistent(e.originalTexture) && AssetDatabase.TryGetGUIDAndLocalFileIdentifier(e.originalTexture, out e.assetGUID, out e.localId);
                            e.textureKind = e.restorable ? "persistent-asset" : "runtime-unrecoverable";
                        }

                        break;
                    case Kind.Buffer:
                    case Kind.ConstantBuffer:
                        e.restorable = false;
                        e.reason = "No public Shader global binding getter; do not mutate";
                        break;
                }

                if (!e.restorable && string.IsNullOrEmpty(e.reason))
                    e.reason = "absent/zero array or runtime-only texture; do not mutate";
                j.entries.Add(e);
            }

            j.WriteExternal();
            Active = j;
            return j;
        }

        static void Matrix(BinaryWriter w, Matrix4x4 m)
        {
            for (int c = 0; c < 4; c++)
                for (int r = 0; r < 4; r++)
                    w.Write(m[r, c]);
        }

        static void Vector(BinaryWriter w, Vector4 v)
        {
            w.Write(v.x);
            w.Write(v.y);
            w.Write(v.z);
            w.Write(v.w);
        }

        void WriteExternal()
        {
            using (var stream = new FileStream(externalPath, FileMode.CreateNew, FileAccess.Write, FileShare.Read))
                using (var w = new BinaryWriter(stream))
                {
                    w.Write(0x34364a47);
                    w.Write(1);
                    w.Write(sourceId);
                    w.Write(entries.Count);
                    foreach (var e in entries)
                    {
                        w.Write(e.spec.name);
                        w.Write((int)e.spec.kind);
                        w.Write(e.restorable);
                        w.Write(e.reason ?? "");
                        w.Write(e.scalar);
                        w.Write(e.integer);
                        Vector(w, e.vector);
                        Matrix(w, e.matrix);
                        w.Write(e.textureKind ?? "");
                        w.Write(e.assetGUID ?? "");
                        w.Write(e.localId);
                        w.Write(e.floats?.Length ?? 0);
                        if (e.floats != null)
                            foreach (var v in e.floats)
                                w.Write(v);
                        w.Write(e.vectors?.Length ?? 0);
                        if (e.vectors != null)
                            foreach (var v in e.vectors)
                                Vector(w, v);
                        w.Write(e.matrices?.Length ?? 0);
                        if (e.matrices != null)
                            foreach (var v in e.matrices)
                                Matrix(w, v);
                    }

                    w.Flush();
                    stream.Flush(true);
                }

            using (var h = SHA256.Create())
                using (var f = File.OpenRead(externalPath))
                    backupSHA256 = BitConverter.ToString(h.ComputeHash(f)).Replace("-", "").ToLowerInvariant();
            externalVerified = VerifyExternal();
            if (!externalVerified)
                throw new IOException("external backup verification failed");
        }

        static bool Bits(float a, float b)
        {
            return BitConverter.SingleToInt32Bits(a) == BitConverter.SingleToInt32Bits(b);
        }

        static bool VectorBits(Vector4 a, Vector4 b)
        {
            for (int i = 0; i < 4; i++)
                if (!Bits(a[i], b[i]))
                    return false;
            return true;
        }

        static bool MatrixBits(Matrix4x4 a, Matrix4x4 b)
        {
            for (int i = 0; i < 16; i++)
                if (!Bits(a[i], b[i]))
                    return false;
            return true;
        }

        static bool ReadVector(BinaryReader r, Vector4 expected)
        {
            for (int i = 0; i < 4; i++)
                if (!Bits(r.ReadSingle(), expected[i]))
                    return false;
            return true;
        }

        static bool ReadMatrix(BinaryReader r, Matrix4x4 expected)
        {
            for (int c = 0; c < 4; c++)
                for (int row = 0; row < 4; row++)
                    if (!Bits(r.ReadSingle(), expected[row, c]))
                        return false;
            return true;
        }

        bool VerifyExternal()
        {
            using (var r = new BinaryReader(File.OpenRead(externalPath)))
            {
                if (r.ReadInt32() != 0x34364a47 || r.ReadInt32() != 1 || r.ReadString() != sourceId || r.ReadInt32() != entries.Count)
                    return false;
                foreach (var e in entries)
                {
                    if (r.ReadString() != e.spec.name || r.ReadInt32() != (int)e.spec.kind || r.ReadBoolean() != e.restorable || r.ReadString() != (e.reason ?? ""))
                        return false;
                    if (!Bits(r.ReadSingle(), e.scalar) || r.ReadInt32() != e.integer || !ReadVector(r, e.vector) || !ReadMatrix(r, e.matrix))
                        return false;
                    if (r.ReadString() != (e.textureKind ?? "") || r.ReadString() != (e.assetGUID ?? "") || r.ReadInt64() != e.localId)
                        return false;
                    if (r.ReadInt32() != (e.floats?.Length ?? 0))
                        return false;
                    if (e.floats != null)
                        foreach (float v in e.floats)
                            if (!Bits(r.ReadSingle(), v))
                                return false;
                    if (r.ReadInt32() != (e.vectors?.Length ?? 0))
                        return false;
                    if (e.vectors != null)
                        foreach (var v in e.vectors)
                            if (!ReadVector(r, v))
                                return false;
                    if (r.ReadInt32() != (e.matrices?.Length ?? 0))
                        return false;
                    if (e.matrices != null)
                        foreach (var v in e.matrices)
                            if (!ReadMatrix(r, v))
                                return false;
                }

                return r.BaseStream.Position == r.BaseStream.Length;
            }
        }

        // Call on the ENTIRE renderer mutation inventory before normal Play/render.
        // This does not intercept or excuse untracked setters inside product passes.
        public void RequireRecoverable(IEnumerable<string> mutationNames)
        {
            if (!externalVerified)
                throw new InvalidOperationException("external backup not verified");
            foreach (string name in mutationNames)
            {
                var e = entries.SingleOrDefault(x => x.spec.name == name);
                if (e == null || !e.restorable)
                    throw new InvalidOperationException("unbacked global mutation: " + name);
            }
        }

        public void BeforeMutation(string name, int newArrayLength = -1)
        {
            RequireRecoverable(new[]{name});
            var e = entries.Single(x => x.spec.name == name);
            int old = e.floats?.Length ?? e.vectors?.Length ?? e.matrices?.Length ?? -1;
            if (newArrayLength >= 0 && newArrayLength != old)
                throw new InvalidOperationException("global array length change forbidden");
            e.mutated = true;
        }

        public void RestoreMarked()
        {
            // No buffer setters. Assets and built-ins are retained references, never
            // destroyed/recreated from a guessed EntityId or surrounding colours.
            foreach (var e in entries.Where(x => x.mutated))
            {
                if (!e.restorable)
                    throw new InvalidOperationException("unrestorable global: " + e.spec.name);
                string n = e.spec.name;
                switch (e.spec.kind)
                {
                    case Kind.Float:
                        Shader.SetGlobalFloat(n, e.scalar);
                        break;
                    case Kind.LegacyInt:
                        Shader.SetGlobalFloat(n, e.scalar);
                        break;
                    case Kind.Integer:
                        Shader.SetGlobalInteger(n, e.integer);
                        break;
                    case Kind.Vector:
                        Shader.SetGlobalVector(n, e.vector);
                        break;
                    case Kind.Matrix:
                        Shader.SetGlobalMatrix(n, e.matrix);
                        break;
                    case Kind.Texture:
                        if (e.textureKind != "null" && !e.originalTexture)
                            throw new InvalidOperationException("original texture lifetime lost");
                        Shader.SetGlobalTexture(n, e.originalTexture);
                        break;
                    case Kind.FloatArray:
                        Shader.SetGlobalFloatArray(n, e.floats);
                        break;
                    case Kind.VectorArray:
                        Shader.SetGlobalVectorArray(n, e.vectors);
                        break;
                    case Kind.MatrixArray:
                        Shader.SetGlobalMatrixArray(n, e.matrices);
                        break;
                    default:
                        throw new InvalidOperationException("unsupported restore type");
                }
            }
        // Getter-by-getter equality verification is a required caller step before
        // clearing Active; this helper does not clear the only recovery handle.
        }

        public string[] VerifyMarked()
        {
            var errors = new List<string>();
            foreach (var e in entries.Where(x => x.mutated))
            {
                string n = e.spec.name;
                bool same = false;
                switch (e.spec.kind)
                {
                    case Kind.Float:
                    case Kind.LegacyInt:
                        same = Bits(Shader.GetGlobalFloat(n), e.scalar);
                        break;
                    case Kind.Integer:
                        same = Shader.GetGlobalInteger(n) == e.integer;
                        break;
                    case Kind.Vector:
                        same = VectorBits(Shader.GetGlobalVector(n), e.vector);
                        break;
                    case Kind.Matrix:
                        same = MatrixBits(Shader.GetGlobalMatrix(n), e.matrix);
                        break;
                    case Kind.Texture:
                        same = Shader.GetGlobalTexture(n) == e.originalTexture;
                        break;
                    case Kind.FloatArray:
                        var a = Shader.GetGlobalFloatArray(n);
                        same = a != null && a.Length == e.floats.Length && a.Zip(e.floats, Bits).All(v => v);
                        break;
                    case Kind.VectorArray:
                        var b = Shader.GetGlobalVectorArray(n);
                        same = b != null && b.Length == e.vectors.Length && b.Zip(e.vectors, VectorBits).All(v => v);
                        break;
                    case Kind.MatrixArray:
                        var c = Shader.GetGlobalMatrixArray(n);
                        same = c != null && c.Length == e.matrices.Length && c.Zip(e.matrices, MatrixBits).All(v => v);
                        break;
                }

                if (!same)
                    errors.Add(n);
            }

            return errors.ToArray();
        }

        public void ReleaseHandleAfterVerified()
        {
            if (!externalVerified || VerifyMarked().Length != 0)
                throw new InvalidOperationException("restore not verified; preserve recovery handle");
            // Drop only journal references, never Dispose/Destroy original textures
            // or user buffers. No forced GC. External backup stays on disk.
            entries.Clear();
            if (Active == this)
                Active = null;
        }
    }

    public enum Kind
    {
        Float,
        LegacyInt,
        Integer,
        Vector,
        Matrix,
        Texture,
        FloatArray,
        VectorArray,
        MatrixArray,
        Buffer,
        ConstantBuffer
    }

    public sealed class Spec
    {
        public string name;
        public Kind kind;
    }

    public sealed class Entry
    {
        public Spec spec;
        public float scalar;
        public int integer;
        public Vector4 vector;
        public Matrix4x4 matrix;
        public float[] floats;
        public Vector4[] vectors;
        public Matrix4x4[] matrices;
        public Texture originalTexture;
        public string textureKind, assetGUID;
        public long localId;
